const chars = $input.first().json.normalized_alignment.characters;
const startTimes = $input.first().json.normalized_alignment.character_start_times_seconds;
const endTimes = $input.first().json.normalized_alignment.character_end_times_seconds;

let subtitles = [];
let buffer = '';
let startTime = null;
let endTime = null;
let wordCounter = 0;

for (let i = 0; i < chars.length; i++) {
  const char = chars[i];

  if (buffer === '') {
    startTime = startTimes[i];
  }

  buffer += char;
  endTime = endTimes[i];

  const isWordEnd = char === ' ' || i === chars.length - 1;

  if (isWordEnd) {
    wordCounter++;

    if (wordCounter >= 3 || i === chars.length - 1) {
      const text = buffer.replace(/\b\d+\b\s*/g, '').trim();

      if (text.length > 0) {
        subtitles.push({
          start: startTime,
          end: endTime,
          text: text
        });
      }

      buffer = '';
      wordCounter = 0;
      startTime = null;
      endTime = null;
    }
  }
}

// Função para converter segundos em tempo SRT
function secondsToSRTTime(seconds) {
  const date = new Date(0);
  date.setSeconds(Math.floor(seconds));
  const iso = date.toISOString().substr(11, 8);
  const milliseconds = Math.round((seconds % 1) * 1000).toString().padStart(3, '0');
  return `${iso},${milliseconds}`;
}

// Geração do conteúdo SRT
const srtLines = subtitles.map((entry, index) => {
  return `${index + 1}\n${secondsToSRTTime(entry.start)} --> ${secondsToSRTTime(entry.end)}\n${entry.text}\n\n`;
});

// Retorno do conteúdo como JSON
return [
  {
    json: {
      srt: srtLines.join('')
    }
  }
];

const base64Audio = $('ElevenLabs').first().json.audio_base64;

return [
  {
    binary: {
      audio: {
        data: base64Audio,
        mimeType: 'audio/mpeg',
        fileName: 'voz.mp3'
      }
    },
    json: {}
  }
];

// GetAudioDuration (Code node)
// Extrai a duração total do áudio a partir dos timestamps do ElevenLabs1
const alignment = $items('ElevenLabs')[0].json.normalized_alignment;
if (!alignment || !alignment.character_end_times_seconds) {
  throw new Error('normalized_alignment não encontrado em ElevenLabs');
}
// Pega o último tempo de fim de caractere como duração total
const ends = alignment.character_end_times_seconds;
const audioDuration = ends[ends.length - 1];

// Retorna no JSON para ser usado adiante
return [{
  json: {
    audioDuration,
  },
}];

// --- INPUTS ---
// Mantemos as entradas originais
const srtLink = $('DriveLegenda').first().json.webContentLink;
const audioDuration = $('GetAudioDuration').first().json.audioDuration;
const audioUrl = $('DriveAudio').first().json.webContentLink;

// --- ENTRADAS PARA O SOUNDTRACK (Conforme sua solicitação) ---
// 1. A URL da música continua vindo do nó original 'UploadSoundTrack'
const musicUrl = $('UploadSoundTrack').first().json.webContentLink;

// 2. A DURAÇÃO da música é a única informação que pegamos do 'Verify Soundtrack'
const soundtrackDuration = $('Verify Soundtrack').first().json.meta.duration;


// --- LÓGICA DAS IMAGENS (permanece inalterada) ---
const imagensGemini = $('UploadCenas').all().map(item => item.json);
let tempoAcumulado = 0;
const clipesImagem = [];

const duracaoPorImagem = imagensGemini.length > 0 ? audioDuration / imagensGemini.length : audioDuration;

imagensGemini.forEach((imagem) => {
  const link = imagem.webContentLink;
  const restante = audioDuration - tempoAcumulado;
  if (restante > 0) {
    clipesImagem.push({
      asset: { type: "image", src: link },
      start: tempoAcumulado,
      length: Math.min(duracaoPorImagem, restante),
      fit: "cover",
      transition: { in: "fade", out: "fade" }
    });
    tempoAcumulado += duracaoPorImagem;
  }
});


// --- NOVA LÓGICA DE LOOP PARA O SOUNDTRACK (permanece inalterada) ---
const soundtrackClips = [];
let soundtrackTempoAcumulado = 0;

const numeroDeLoops = Math.ceil(audioDuration / soundtrackDuration);

for (let i = 0; i < numeroDeLoops; i++) {
  const tempoRestanteVideo = audioDuration - soundtrackTempoAcumulado;

  if (tempoRestanteVideo > 0) {
    const clipe = {
      asset: {
        type: "audio",
        src: musicUrl, // Usa a URL do 'UploadSoundTrack'
        volume: 0.1
      },
      start: soundtrackTempoAcumulado,
      length: Math.min(soundtrackDuration, tempoRestanteVideo) // Usa a duração do 'Verify Soundtrack'
    };
    soundtrackClips.push(clipe);
    soundtrackTempoAcumulado += soundtrackDuration;
  }
}


// --- CONSTRUÇÃO DA TIMELINE FINAL (permanece inalterada) ---
const timeline = {
  tracks: [
    // Trilha 1: Legendas
    {
      clips: [
        {
          asset: {
            type: "caption",
            src: srtLink,
            font: {
              family: "Open Sans",
              color: "#FFFF00",
              size: 40,
              stroke: "#000000",
              strokeWidth: 2
            },
            alignment: {
              horizontal: "center",
              vertical: "center"
            },
            margin: {
              top: 0.6
            }
          },
          start: 0,
          length: audioDuration
        }
      ]
    },
    // Trilha 2: Imagens
    {
      clips: clipesImagem
    },
    // Trilha 3: Áudio Principal/Narração
    {
      clips: [
        {
          asset: {
            type: "audio",
            src: audioUrl
          },
          start: 0,
          length: audioDuration
        }
      ]
    },
    // Trilha 4: Música de fundo em loop
    {
      clips: soundtrackClips
    }
  ]
};


// --- OUTPUT (permanece inalterado) ---
const output = {
  format: 'mp4',
  resolution: 'hd',
  fps: 30,
  aspectRatio: '16:9'
};

return [
  {
    json: {
      timeline,
      output
    }
  }
];

const query = $json.query || '';
return {
  json: {
    query: query.replace(/\n/g, ' ').trim()
  }
};

